#include "script_builder.hpp"
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <set>
#include <sstream>
namespace penta::research {
namespace {
std::string number(double value){if(!std::isfinite(value))throw ScriptError("Spatial settings must be finite.");std::ostringstream out;out<<std::setprecision(17)<<value;return out.str();}
std::string join(const std::vector<std::string>& entries,const char* separator=","){std::string result;for(const auto& entry:entries){if(!result.empty())result+=separator;result+=entry;}return result;}
std::string diagnostic(const language::AnalysisResult& result){for(const auto& d:result.diagnostics)if(d.severity==language::Severity::Error)return d.code+": "+d.message;return "Generated spatial source did not check.";}
bool pure(const language::ExprPtr& expression){
    if(!expression)return false;
    using language::ExprKind;
    switch(expression->kind){case ExprKind::IntegerLiteral:case ExprKind::RealLiteral:case ExprKind::Reference:case ExprKind::Group:case ExprKind::Unary:case ExprKind::Binary:case ExprKind::PentConstructor:case ExprKind::MatrixLiteral:case ExprKind::Range:case ExprKind::TupleLiteral:break;
        case ExprKind::Call:{static const std::set<std::string> functions{"sin","cos","tan","exp","log","sqrt","sinh","cosh","tanh","asin","acos","atan","atan2","abs","floor","ceil","round","sign","min","max","conj","scalar","pure","norm2","coeff"};if(!functions.contains(expression->text))return false;break;}
        default:return false;
    }
    return std::all_of(expression->children.begin(),expression->children.end(),pure);
}
void bounded(const std::string& expression){if(expression.empty()||expression.size()>4096||expression.find('\0')!=std::string::npos)throw ScriptError("Enter one bounded nonempty mathematical expression.");}
void scalar(const std::string& type,const std::string& value,const language::AnalysisOptions& options){bounded(value);const auto checked=language::analyse(type+" research_checked_value="+value+";",options);if(!checked.ok())throw ScriptError(diagnostic(checked));if(checked.program.statements.size()!=1||checked.program.statements[0].kind!=language::StatementKind::Declaration||!pure(checked.program.statements[0].expression))throw ScriptError("Value controls accept one pure expression without statements or file access.");}
void function(const std::string& source,const language::AnalysisOptions& options){const auto checked=language::analyse(source,options);if(!checked.ok())throw ScriptError(diagnostic(checked));if(checked.program.statements.size()!=1||!checked.program.statements[0].function||checked.program.statements[0].function->body.size()!=1||checked.program.statements[0].function->body[0].kind!=language::StatementKind::Return||!pure(checked.program.statements[0].function->body[0].expression))throw ScriptError("Model controls accept one pure native expression, without injected statements or extra definitions.");}
void identifier(const std::string& name,std::set<std::string>& names){if(name.empty()||name.size()>64||!((name[0]>='A'&&name[0]<='Z')||(name[0]>='a'&&name[0]<='z')||name[0]=='_'))throw ScriptError("Native parameter names require ASCII identifiers.");for(char c:name)if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='_'))throw ScriptError("Native parameter names require ASCII identifiers.");if(name.rfind("research_",0)==0||!names.insert(name).second)throw ScriptError("Use unique parameters outside the spatial coordinate/reserved research_ names.");}
}
std::string generateSpatialScript(const Configuration& c,bool preflight){
    if(auto source=generateExtendedSpatialScript(c,preflight))return *source;
    if(c.mode!=Mode::Pde&&c.mode!=Mode::Geometry&&c.mode!=Mode::Mechanics)throw ScriptError("Select a spatial/mechanics Research Explorer mode.");
    if(!std::isfinite(c.gamma)||c.gamma<0||c.gamma>1||!std::isfinite(c.maximumSeconds)||c.maximumSeconds<=0||c.maximumSeconds>3600||c.threads<0||c.threads>64||c.parameters.size()>16)throw ScriptError("Check algebra gamma, native wall/thread budget and parameter count.");
    language::AnalysisOptions options;options.gamma=c.gamma;std::set<std::string> names{"t","x","y","u","v","q","p","domain_x","domain_y"};std::vector<std::string> declarations,bindings,values;
    for(const auto& parameter:c.parameters){if(parameter.type!="real"&&parameter.type!="pentarnion")throw ScriptError("Native parameters are real or pentarnion.");identifier(parameter.name,names);scalar(parameter.type,parameter.value,options);declarations.push_back(parameter.type+" "+parameter.name);bindings.push_back(parameter.name+"=("+parameter.value+")");values.push_back("("+parameter.value+")");}
    const auto parameters=declarations.empty()?std::string():","+join(declarations),bindingRecord="options("+join(bindings)+")";
    std::string source="% Generated by Research Explorer. Inspect this native model before Run.\nuse_algebra(\"A_gamma\",gamma="+number(c.gamma)+");\nclear;\nrng(5489);\n";
    if(c.mode==Mode::Pde){
        const auto& p=c.spatial.pde;const auto width=p.valueType=="pentarnion"?5u:1u;for(double value:{c.t0,c.t1,c.sampleStep,p.lengthX,p.lengthY,p.diffusion,p.timeStep})if(!std::isfinite(value))throw ScriptError("PDE settings must be finite.");
        if((p.dimension!=1&&p.dimension!=2)||(p.valueType!="real"&&p.valueType!="pentarnion")||p.nx<3||p.nx>65||p.ny<3||p.ny>65||p.lengthX<=0||p.lengthY<=0||p.diffusion<0||p.timeStep<=0||c.t1<=c.t0||c.sampleStep<=0||p.component<0||p.component>=static_cast<int>(width)||(p.method!="fd"&&p.method!="fem")||(p.dimension==2&&p.method!="fd")||(p.integrator!="rk4"&&p.integrator!="imex_euler")||(p.boundary!="periodic"&&p.boundary!="dirichlet"&&p.boundary!="neumann"))throw ScriptError("Check PDE dimension/type, positive grid/time scales, coefficient, FD/P1FE, integrator and boundary choices.");
        const auto samples=std::ceil((static_cast<long double>(c.t1)-c.t0)/c.sampleStep)+2,nodes=static_cast<long double>(p.nx)*(p.dimension==2?p.ny:1);if(samples>240||samples*nodes*width>500000||(c.t1-c.t0)/p.timeStep>200000)throw ScriptError("PDE Explorer retains at most240 frames/500000 coefficients and200000 steps. Increase time/sample step or reduce the grid/horizon.");
        bounded(p.initial);bounded(p.reaction);scalar(p.valueType,p.boundaryValue,options);
        const auto initialModel="native function "+p.valueType+" research_initial_profile(real x,real y,real domain_x,real domain_y"+parameters+"){return "+p.initial+";}\n";
        const auto reactionModel="native function "+p.valueType+" research_reaction("+p.valueType+" u,real t,real x"+(p.dimension==2?",real y":"")+",real domain_x,real domain_y"+parameters+"){return "+p.reaction+";}\n";function(initialModel,options);function(reactionModel,options);source+=initialModel+reactionModel;
        if(preflight)source+="display(\"PDE model checked; no field solve was requested.\","+std::to_string(p.nx)+","+std::to_string(p.dimension==2?p.ny:1)+","+number(static_cast<double>(samples*nodes*width))+");\n";
        else{
            auto grid=[&](double length,int count){return "linspace(0.0,"+number(p.boundary=="periodic"?length*(count-1)/count:length)+","+std::to_string(count)+")";};
            source+="matrix research_x="+grid(p.lengthX,p.nx)+";\n";if(p.dimension==2)source+="matrix research_y="+grid(p.lengthY,p.ny)+";\n";
            source+="matrix research_initial=zeros("+std::to_string(p.dimension==2?p.ny:1)+","+std::to_string(p.nx)+")"+(width==5?"*(1+0*i)":"")+";\nfor(research_row=1:"+std::to_string(p.dimension==2?p.ny:1)+"){for(research_column=1:"+std::to_string(p.nx)+"){research_initial(research_row,research_column)=research_initial_profile(research_x(research_column),"+(p.dimension==2?"research_y(research_row)":"0.0")+","+number(p.lengthX)+","+number(p.lengthY)+(values.empty()?std::string():","+join(values))+");}}\n";
            std::vector<std::string> fixed{"domain_x="+number(p.lengthX),"domain_y="+number(p.lengthY)};fixed.insert(fixed.end(),bindings.begin(),bindings.end());
            const auto solver="parameters=options("+join(fixed)+"),integrator="+quote(p.integrator)+",boundary="+quote(p.boundary)+",diffusion="+number(p.diffusion)+",t0="+number(c.t0)+",t1="+number(c.t1)+",time_step="+number(p.timeStep)+",sample_step="+number(c.sampleStep)+",threads="+std::to_string(c.threads)+",max_wall_seconds="+number(c.maximumSeconds);
            source+="record research_result="+std::string(p.dimension==2?"pdesolve2(research_reaction,research_x,research_y,research_initial,options(":"pdesolve(research_reaction,research_x,research_initial,options(")+solver;
            if(p.dimension==2){source+=",length_x="+number(p.lengthX)+",length_y="+number(p.lengthY);if(p.boundary=="dirichlet")source+=",boundary_value=("+p.boundaryValue+")";}
            else{source+=",method="+quote(p.method)+",length="+number(p.lengthX);if(p.boundary=="dirichlet")source+=",left=("+p.boundaryValue+"),right=("+p.boundaryValue+")";}
            source+="));\ndisplay(\"Native PDE steps and observed threads:\",research_result.steps,research_result.threads_used);\nfigure(60,\"Name\",\"Research Explorer: native PDE field\",\"NumberTitle\",\"off\");clf;\n";
            if(p.dimension==1)source+="matrix research_coordinate_field=pdecoeff(research_result,"+std::to_string(p.component)+");subplot(1,2,1);plot(research_x,research_coordinate_field(end,:));title(\"Final stored field coefficient\");xlabel(\"x\");subplot(1,2,2);imagesc(research_x,research_result.t,research_coordinate_field);title(\"Stored space-time field\");xlabel(\"x\");ylabel(\"t\");\n";
            else source+="matrix research_final_slice=pdeslice(research_result,length(research_result.t),"+std::to_string(p.component)+");subplot(1,2,1);imagesc(research_x,research_y,research_final_slice);title(\"Final stored coefficient\");subplot(1,2,2);surf(research_x,research_y,research_final_slice);title(\"A projection of the retained field\");\n";
            source+="figure(61,\"Name\",\"Research Explorer: saved PDE playback\",\"NumberTitle\",\"off\");clf;animatefield(research_result,options(component="+std::to_string(p.component)+",fps=10,max_frames=240));\n";
        }
    }else if(c.mode==Mode::Geometry){
        const auto& g=c.spatial.geometry;const int dimension=g.output=="real3"?3:5;for(double value:{g.u0,g.u1,g.v0,g.v1})if(!std::isfinite(value))throw ScriptError("Chart bounds must be finite.");if((g.output!="real3"&&g.output!="real5"&&g.output!="pentarnion")||g.u1<=g.u0||g.v1<=g.v0||g.nu<3||g.nv<3||g.nu>51||g.nv>51)throw ScriptError("Geometry uses a three/five-coordinate embedding and a bounded3..51 by3..51 parameter grid.");std::set<int> axes;for(int axis:g.projection)if(axis<1||axis>dimension||!axes.insert(axis).second)throw ScriptError("Choose three distinct one-based projection coordinates within the complete embedding.");
        std::vector<std::string> coordinates,outputs;for(int d=0;d<dimension;++d){bounded(g.coordinates[static_cast<std::size_t>(d)]);function("native function real research_coordinate(real u,real v"+parameters+"){return "+g.coordinates[static_cast<std::size_t>(d)]+";}",options);coordinates.push_back("("+g.coordinates[static_cast<std::size_t>(d)]+")");outputs.push_back("real coordinate"+std::to_string(d+1));}
        std::string embedding;if(g.output=="pentarnion"){static const std::array<const char*,5> basis{"","*i","*j","*k","*ell"};for(int d=0;d<5;++d){if(d)embedding+="+";embedding+=coordinates[static_cast<std::size_t>(d)]+basis[static_cast<std::size_t>(d)];}}else embedding=join(coordinates);
        source+="native function "+(g.output=="pentarnion"?std::string("pentarnion"):"["+join(outputs)+"]")+" research_surface(real u,real v"+parameters+"){return "+embedding+";}\n";
        if(preflight)source+="display(\"Embedding checked; no mesh or curvature evaluation was requested.\","+std::to_string(dimension)+","+std::to_string(g.nu*g.nv)+");\n";
        else source+="record research_mesh=paramesh(@research_surface,linspace("+number(g.u0)+","+number(g.u1)+","+std::to_string(g.nu)+"),linspace("+number(g.v0)+","+number(g.v1)+","+std::to_string(g.nv)+"),options(parameters="+bindingRecord+",threads="+std::to_string(c.threads)+"));\nrecord research_result=meshinfo(research_mesh);display(\"Complete embedding dimension and induced Euclidean area:\",research_result.embedding_dimension,research_result.area);\nrecord research_chart=chartgeometry(@research_surface,["+number(g.u0*.5+g.u1*.5)+","+number(g.v0*.5+g.v1*.5)+"],options(parameters="+bindingRecord+"));display(\"Center chart with explicitly induced Euclidean metric:\",research_chart);\nfigure(60,\"Name\",\"Research Explorer: native geometry\",\"NumberTitle\",\"off\");clf;meshplot(research_mesh,options(projection=["+std::to_string(g.projection[0])+","+std::to_string(g.projection[1])+","+std::to_string(g.projection[2])+"]));title(\"Projection; the complete embedding is retained\");caption(\"Metric: induced Euclidean coefficient coordinates\");\n";
    }else{
        const auto& m=c.spatial.mechanics;for(double value:{c.t0,c.t1,c.sampleStep,m.timeStep})if(!std::isfinite(value))throw ScriptError("Mechanics settings must be finite.");if(c.t1<=c.t0||c.sampleStep<=0||m.timeStep<=0||(c.t1-c.t0)/m.timeStep>200000||(std::ceil((c.t1-c.t0)/c.sampleStep)+2)*8>500000)throw ScriptError("Use a positive mechanics interval/step within200000 steps and500000 retained diagnostic coordinates.");if((m.form!="newton"&&m.form!="lagrangian"&&m.form!="hamiltonian")||(m.form=="newton"&&m.method!="verlet"&&m.method!="rk4")||(m.form=="lagrangian"&&m.method!="rk4")||(m.form=="hamiltonian"&&m.method!="midpoint"))throw ScriptError("Choose Newton Verlet/RK4, Lagrangian RK4, or Hamiltonian midpoint.");bounded(m.expression);scalar("real",m.initialQ,options);scalar("real",m.initialSecond,options);scalar("real",m.mass,options);
        const auto model="native function real research_model(real t,real q"+(m.form=="newton"?std::string():m.form=="hamiltonian"?",real p":",real v")+parameters+"){return "+m.expression+";}\n";function(model,options);source+=model;
        if(preflight)source+="display(\"Mechanics expression checked; no integration was requested.\");\n";
        else{source+="record research_result=mechanics(research_model,("+m.initialQ+"),("+m.initialSecond+"),options(form="+quote(m.form)+",method="+quote(m.method)+",parameters="+bindingRecord+",t0="+number(c.t0)+",t1="+number(c.t1)+",time_step="+number(m.timeStep)+",sample_step="+number(c.sampleStep)+",max_wall_seconds="+number(c.maximumSeconds);if(m.form=="newton")source+=",mass=("+m.mass+")";source+="));\ndisplay(\"Native mechanics form, second-input meaning and steps:\",research_result.form,research_result.second_input,research_result.steps);\nfigure(60,\"Name\",\"Research Explorer: native mechanics\",\"NumberTitle\",\"off\");clf;subplot(2,2,1);plot(research_result.t,research_result.q(:,1));title(\"Configuration coordinate\");xlabel(\"t\");ylabel(\"q\");subplot(2,2,2);plot(research_result.t,research_result.v(:,1));title(\"Velocity\");xlabel(\"t\");subplot(2,2,3);plot(research_result.q(:,1),research_result.p(:,1));title(\"Position and canonical momentum\");xlabel(\"q\");ylabel(\"p\");subplot(2,2,4);plot(research_result.t,research_result."+std::string(m.form=="newton"?"kinetic_energy":"energy")+");title("+quote(m.form=="newton"?"Kinetic energy only":"Defined Lagrangian/Hamiltonian energy")+");xlabel(\"t\");\n";}
    }
    const auto checked=language::analyse(source,options);if(!checked.ok())throw ScriptError(diagnostic(checked));return source;
}
}
